const payload = $json.body || $json;
const limit = Number(payload.limit || 12);
const query = ((payload.query || payload.message || '').toString() || '').trim().toLowerCase();
return [{
  json: {
    workflow_execution_id: $execution.id,
    query: query,
    category: (payload.category || '').toString(),
    serviceId: (payload.service || payload.service_id || '').toString(),
    language: ((payload.language || 'es').toString().toLowerCase() === 'en') ? 'en' : 'es',
    session_id: (payload.session_id || '').toString(),
    customer_id: (payload.customer_id || '').toString(),
    channel: (payload.channel || 'web').toString(),
    intent: (payload.intent || 'SERVICE_INFORMATION').toString(),
    selected_tool: (payload.selected_tool || payload.tool || 'SERVICE_CATALOG').toString(),
    limit: Number.isFinite(limit) && limit > 0 ? limit : 12,
    useApi: ((payload.service_catalog_url || payload.serviceCatalogUrl || payload.config?.service_catalog_url || '').toString().trim().length > 4)
  }
}];

const catalog = [
  { id: 'credit_education', name: 'Credit education', category: 'Credit Services', description: 'Credit education, review and educational guidance.', active: true, price: null, requires_consultation: true, appointment_type: 'consultation_credit', required_documents: ['ID', 'Income source'], faq_tags: ['credit','education'] },
  { id: 'credit_analysis', name: 'Credit analysis', category: 'Credit Services', description: 'Credit analysis and readiness review.', active: true, price: null, requires_consultation: true, appointment_type: 'consultation_credit', required_documents: ['Credit report'], faq_tags: ['credit','analysis'] },
  { id: 'credit_repair_assistance', name: 'Credit repair assistance', category: 'Credit Services', description: 'Guidance on credit improvement steps and cleanup strategy.', active: true, price: null, requires_consultation: true, appointment_type: 'consultation_credit', required_documents: ['ID', 'Credit report'], faq_tags: ['repair','dispute'] },
  { id: 'tax_individual', name: 'Individual tax preparation', category: 'Tax Services', description: 'Individual tax preparation support and intake.', active: true, price: null, requires_consultation: true, appointment_type: 'tax_preparation', required_documents: ['W-2', '1099'], faq_tags: ['tax','individual'] },
  { id: 'tax_self_employed', name: 'Self-employed tax preparation', category: 'Tax Services', description: 'Tax prep support for self-employed clients.', active: true, price: null, requires_consultation: true, appointment_type: 'tax_preparation', required_documents: ['Form 1099', 'Income logs'], faq_tags: ['tax','self-employed'] },
  { id: 'tax_small_business', name: 'Small business tax preparation', category: 'Tax Services', description: 'Tax prep support for small business filings.', active: true, price: null, requires_consultation: true, appointment_type: 'tax_preparation', required_documents: ['Profit and loss', 'Bank statements'], faq_tags: ['tax','smb'] },
  { id: 'llc_formation', name: 'LLC formation', category: 'Business Formation', description: 'Guidance on LLC formation and filing readiness.', active: true, price: null, requires_consultation: true, appointment_type: 'business_formation', required_documents: ['ID', 'State address'], faq_tags: ['llc','formation'] },
  { id: 'ein_assistance', name: 'EIN assistance', category: 'Business Formation', description: 'Guidance for obtaining an EIN and business readiness.', active: true, price: null, requires_consultation: true, appointment_type: 'business_formation', required_documents: ['ID', 'Business info'], faq_tags: ['ein','formation'] },
  { id: 'business_funding_preparation', name: 'Business funding preparation', category: 'Business Funding', description: 'Preparation of documents and lender matching readiness.', active: true, price: null, requires_consultation: true, appointment_type: 'funding', required_documents: ['Credit report', 'Bank statements'], faq_tags: ['funding','loan'] },
  { id: 'loan_document_preparation', name: 'Loan document preparation', category: 'Loan Preparation', description: 'Loan document readiness and preparation support.', active: true, price: null, requires_consultation: true, appointment_type: 'loan_preparation', required_documents: ['ID', 'Income proof'], faq_tags: ['loan','documents'] },
  { id: 'usda_homebuying', name: 'USDA assistance', category: 'Home Buying Assistance', description: 'USDA-style home buying readiness and guidance.', active: true, price: null, requires_consultation: true, appointment_type: 'home_buying', required_documents: ['Credit report', 'ID'], faq_tags: ['home','usda'] },
  { id: 'fha_homebuying', name: 'FHA assistance', category: 'Home Buying Assistance', description: 'FHA program guidance and preparation support.', active: true, price: null, requires_consultation: true, appointment_type: 'home_buying', required_documents: ['Credit report', 'ID'], faq_tags: ['home','fha'] },
  { id: 'conventional_homebuying', name: 'Conventional financing guidance', category: 'Home Buying Assistance', description: 'General financing guidance for conventional home loans.', active: true, price: null, requires_consultation: true, appointment_type: 'home_buying', required_documents: ['Credit report', 'Income proof'], faq_tags: ['home','conventional'] }
];

const q = $json.query || '';
const lower = q.toLowerCase();
const terms = lower.split(/\s+/).filter(Boolean);
const catFilter = ($json.category || '').toLowerCase();
const idFilter = ($json.serviceId || '').toLowerCase();
const limit = Number($json.limit || 12);

let filtered = catalog.filter((s) => s.active);
if (catFilter) {
  filtered = filtered.filter((s) => s.category.toLowerCase().includes(catFilter));
}
if (idFilter) {
  filtered = filtered.filter((s) => s.id.toLowerCase() === idFilter || s.name.toLowerCase().includes(idFilter));
}
if (lower) {
  filtered = filtered.filter((s) => {
    const all = `${s.name} ${s.category} ${s.description} ${s.faq_tags.join(' ')}`.toLowerCase();
    return terms.some((t) => all.includes(t));
  });
}
filtered = filtered.slice(0, Math.max(1, limit));

return [{
  json: {
    found: filtered.length > 0,
    results: filtered,
    confidence: filtered.length > 0 ? 0.93 : 0,
    query: q,
    language: $json.language,
    intent: $json.intent,
    selected_tool: 'SERVICE_CATALOG',
    tool: 'SERVICE_CATALOG',
    service: $json.serviceId || $json.category || 'general',
    session_id: $json.session_id,
    customer_id: $json.customer_id,
    channel: $json.channel
  }
}];

const base = $json || {};
const response = base.body || base.data || base;
const results = Array.isArray(response.results) ? response.results : (Array.isArray(base.results) ? base.results : []);
const found = Boolean(response.found ?? base.found ?? (results.length > 0));

return [{
  json: {
    found: found,
    results: found ? results : [],
    confidence: Number(response.confidence || base.confidence || 0),
    query: response.query || base.query || '',
    language: response.language || base.language || 'es',
    intent: response.intent || base.intent || 'SERVICE_INFORMATION',
    selected_tool: response.selected_tool || base.selected_tool || 'SERVICE_CATALOG',
    tool: response.tool || base.tool || 'SERVICE_CATALOG',
    service: response.service || base.service || 'general',
    session_id: response.session_id || base.session_id || '',
    customer_id: response.customer_id || base.customer_id || '',
    channel: response.channel || base.channel || 'web',
    raw: response
  }
}];
